<section class="card card-body extension-panel"><h2 class="card-title">발송 이력 <small><?= (int) $history['total'] ?>건</small></h2>
<form method="get" action="<?= $this->e($base) ?>/modules/alimtalk/history"><input type="hidden" name="environment" value="<?= $this->e($environment) ?>"><div class="history-filters"><div><label class="extension-label" for="status">접수 상태</label><select class="select select-bordered select-block" id="status" name="status"><option value="">전체</option><?php foreach (['prepared','sending','accepted','rejected','unknown'] as $status): ?><option value="<?= $this->e($status) ?>"<?= ($values['status'] ?? '') === $status ? ' selected' : '' ?>><?= $this->e($status_labels[$status]) ?></option><?php endforeach ?></select></div><div><label class="extension-label" for="from-date">시작일</label><input class="input input-bordered input-block" id="from-date" type="date" name="from" value="<?= $this->e(is_string($values['from'] ?? null) ? $values['from'] : '') ?>"></div><div><label class="extension-label" for="until-date">종료일</label><input class="input input-bordered input-block" id="until-date" type="date" name="until" value="<?= $this->e(is_string($values['until'] ?? null) ? $values['until'] : '') ?>"></div><button class="btn btn-primary" type="submit">조회</button></div></form>
<div class="table-wrap"><table class="table"><thead><tr><th>요청 시각</th><th>템플릿</th><th>수신번호</th><th>접수</th><th>도달</th></tr></thead><tbody>
<?php foreach ($history['items'] as $item): ?><tr><td data-label="요청 시각"><a class="link" href="<?= $this->e($base) ?>/modules/alimtalk/detail?environment=<?= $this->e($environment) ?>&amp;id=<?= $this->e($item['id']) ?>"><?= $this->e($time($item['created_at'])) ?></a></td><td data-label="템플릿"><?= $this->e($item['template_name']) ?></td><td data-label="수신번호"><?= $this->e($item['phone_mask'] ?: '보관 만료') ?></td><td data-label="접수"><?= $this->e($status_labels[$item['submission']] ?? $item['submission']) ?></td><td data-label="도달"><?= $this->e($status_labels[$item['delivery']] ?? $item['delivery']) ?></td></tr><?php endforeach ?>
<?php if ($history['items'] === []): ?><tr><td colspan="5">조회된 발송이 없습니다.</td></tr><?php endif ?></tbody></table></div>
<?php $query = ['environment' => $environment]; foreach (['status','from','until','template_id'] as $key) if (is_string($values[$key] ?? null)) $query[$key] = $values[$key]; ?>
<nav><?php if ($history['page'] > 1): ?><a class="link" href="?<?= $this->e(http_build_query($query + ['page' => $history['page'] - 1])) ?>">이전</a><?php endif ?><?php if ($history['page'] * 20 < $history['total']): ?><a class="link" href="?<?= $this->e(http_build_query($query + ['page' => $history['page'] + 1])) ?>">다음</a><?php endif ?></nav>
<?php if ($page === 'history'): ?><form method="post" action="<?= $this->e($base) ?>/modules/alimtalk/history"><input type="hidden" name="csrf_token" value="<?= $this->e($csrf_token) ?>"><input type="hidden" name="environment" value="<?= $this->e($environment) ?>"><p>90일이 지난 발송의 수신정보와 메시지 내용을 최대 100건씩 삭제합니다. 중복 방지 식별자와 결과는 유지합니다.</p><button name="action" value="purge" class="secondary btn">보관 만료 개인정보 정리</button></form><?php endif ?></section>
